style.css:
@-moz-document domain("discord.com") {
/* ==========================
      KIUT MACABRO v1
========================== */

:root{

--bg-image:url("https://i.pinimg.com/vwebp/736x/03/4d/56/034d56f722868cae7ad30286fce17e9b.webp");

--main:#8fdfff;
--main2:#bfefff;
--main3:#e6fbff;

--purple:#d8c7ff;

--text:#f7fcff;
--text-muted:#b8d7e8;

--glass:rgba(10,25,50,.55);
--glass2:rgba(30,45,80,.50);

--hover:rgba(143,223,255,.15);
--selected:rgba(143,223,255,.23);

}

/* Fondo */

body,
.appMount__51fd7{

background:
linear-gradient(rgba(8,20,40,.45),rgba(8,20,40,.60)),
var(--bg-image)!important;

background-size:cover!important;
background-position:center!important;
background-attachment:fixed!important;

}

/* Paneles */

[class*="sidebar"],
[class*="content"],
[class*="chat"],
[class*="container"],
[class*="panels"],
[class*="membersWrap"],
[class*="applicationStore"],
[class*="peopleColumn"],
[class*="nowPlayingColumn"]{

background:var(--glass)!important;

backdrop-filter:blur(18px)!important;

}

/* Inputs */

input,
textarea{

background:rgba(255,255,255,.06)!important;

border-radius:14px!important;

color:white!important;

}

/* Botones */

button{

background:linear-gradient(135deg,#7fdcff,#dff9ff)!important;

color:#10304d!important;

border-radius:16px!important;

transition:.25s!important;

font-weight:700!important;

}

button:hover{

transform:translateY(-2px) scale(1.03);

box-shadow:0 0 18px #9ee8ff;

}

/* Canales */

[class*="link"]:hover{

background:var(--hover)!important;

border-radius:12px;

}

[class*="modeSelected"]{

background:var(--selected)!important;

border-left:4px solid var(--main);

}

/* Mensajes */

[class*="message"]:hover{

background:rgba(190,240,255,.08)!important;

border-radius:14px;

}

/* Mensaje seleccionado */

[class*="replying"]{

background:rgba(143,223,255,.22)!important;

border-left:4px solid var(--main);

}

[class*="mentioned"]{

background:rgba(200,240,255,.22)!important;

border-left:4px solid white;

}

/* Links */

a{

color:var(--main)!important;

}

a:hover{

color:white!important;

text-shadow:0 0 10px #9be8ff;

}

/* Texto */

h1,h2,h3,

[class*="title"],

[class*="username"],

[class*="name"]{

color:var(--main2)!important;

}

/* Scroll */

::-webkit-scrollbar{

width:10px;

}

::-webkit-scrollbar-thumb{

background:#8fdfff;

border-radius:20px;

}

::-webkit-scrollbar-track{

background:transparent;

}

/* Selección */

::selection{

background:#8fdfff;

color:#09223c;

}

/* Animación */

*{

transition:
background .20s,
color .20s,
border .20s,
box-shadow .20s;

}

/* Glow */

button:hover,
[class*="modeSelected"],
[class*="replying"]{

box-shadow:0 0 18px rgba(143,223,255,.45);

}

/* Bordes */

img,
video{

border-radius:14px;

}

/* Emoji */

[class*="emoji"]{

filter:drop-shadow(0 0 6px #9fe9ff);

}
}
